-- =====================================================================
-- BachHome · service-inventory · dữ liệu mẫu
-- Kho gồm 2 nhóm:
--   (1) 367 mặt hàng đang bán  -> có product_id, khớp đúng id bên service-product,
--       được trừ khi đơn được xác nhận và hoàn lại khi đơn bị huỷ.
--   (2) 6 vật tư đóng gói -> product_id NULL, chỉ theo dõi trong kho.
-- Số tồn là số giả lập (nguồn không công khai tồn kho), cố định để lần nào chạy cũng như nhau.
-- =====================================================================

-- (0) Dọn tồn kho của bộ sản phẩm mẫu đời đầu (chỉ gắn với product_id 1..7).
--     Sau khi nạp bộ mới, product_id lớn nhất là 367 nên câu này không xoá gì nữa.
DELETE FROM inventory_items
WHERE product_id IS NOT NULL
  AND (SELECT COALESCE(MAX(product_id), 0) FROM inventory_items) < 100;

-- (1) Tồn kho của các sản phẩm đang bán
