-- (2) Vật tư đóng gói phục vụ giao hàng (không gắn sản phẩm bán ra)
INSERT INTO inventory_items (name, product_id, unit, quantity, min_quantity, cost_per_unit, description, active, created_at, updated_at)
SELECT v.name, v.pid, v.unit, v.qty, v.minq, v.cost, v.descr, true, NOW(), NOW()
FROM (VALUES
    ('Thùng carton đóng gói', NULL::bigint, 'cái', 500.00::numeric, 80.00::numeric, 8000.00::numeric, 'Thùng carton 3 lớp dùng để đóng gói đơn hàng.'),
    ('Băng keo đóng gói', NULL::bigint, 'cuộn', 300.00::numeric, 50.00::numeric, 12000.00::numeric, 'Băng keo trong khổ lớn niêm phong thùng hàng.'),
    ('Màng bọc chống sốc (bong bóng khí)', NULL::bigint, 'mét', 1200.00::numeric, 200.00::numeric, 3000.00::numeric, 'Màng xốp hơi bảo vệ hàng dễ vỡ khi vận chuyển.'),
    ('Túi nilon gói hàng', NULL::bigint, 'kg', 150.00::numeric, 30.00::numeric, 25000.00::numeric, 'Túi nilon các cỡ để bọc và phân loại sản phẩm.'),
    ('Xốp chèn hàng', NULL::bigint, 'kg', 80.00::numeric, 20.00::numeric, 40000.00::numeric, 'Hạt xốp / mút chèn lấp khoảng trống trong thùng.'),
    ('Nhãn dán vận chuyển', NULL::bigint, 'tờ', 2000.00::numeric, 300.00::numeric, 500.00::numeric, 'Nhãn in mã đơn và địa chỉ giao hàng.')
) AS v(name, pid, unit, qty, minq, cost, descr)
WHERE NOT EXISTS (SELECT 1 FROM inventory_items WHERE product_id IS NULL);

SELECT setval(pg_get_serial_sequence('inventory_items', 'id'), COALESCE((SELECT MAX(id) FROM inventory_items), 1), true);
